<?php

namespace App\Services\Documents;

use InvalidArgumentException;

/**
 * A small, deliberately limited template language so administrators can edit print layouts without a code deploy
 * and without being able to run code (Blade/PHP are never used for stored templates).
 *
 *   {{ patient.name }}                  value, HTML-escaped
 *   {{{ qr_svg }}}                      raw — only for variables whose name ends in _svg (generated by us, never user data)
 *   {{ l.total }}                       label from the language pack(s)
 *   {{#each items}} ... {{ name }} ... {{/each}}      loop; inside, names resolve against the row first, then the document
 *   {{#if is_copy}} ... {{else}} ... {{/if}}
 */
class SafeTemplate
{
    /** @throws InvalidArgumentException when the template is malformed */
    public function validate(string $template): void
    {
        $this->parse($template);
    }

    public function render(string $template, array $data): string
    {
        return $this->renderNodes($this->parse($template), [$data]);
    }

    /** @return list<array> */
    private function parse(string $template): array
    {
        preg_match_all('/\{\{\{\s*([\w.]+)\s*\}\}\}|\{\{\s*(#each|#if|\/each|\/if|else)?\s*([\w.]*)\s*\}\}/', $template, $matches, PREG_OFFSET_CAPTURE | PREG_SET_ORDER);

        $root = ['kind' => 'root', 'then' => [], 'else' => [], 'inElse' => false];
        $stack = [&$root];
        $cursor = 0;

        $append = function (array $node) use (&$stack): void {
            $top = &$stack[count($stack) - 1];
            $branch = $top['inElse'] ? 'else' : 'then';
            $top[$branch][] = $node;
        };

        foreach ($matches as $match) {
            [$whole, $offset] = $match[0];
            $append(['text', substr($template, $cursor, $offset - $cursor)]);
            $cursor = $offset + strlen($whole);

            if (($match[1][0] ?? '') !== '') {
                if (! str_ends_with($match[1][0], '_svg')) {
                    throw new InvalidArgumentException("Raw output {{{ {$match[1][0]} }}} is only allowed for variables ending in _svg.");
                }
                $append(['raw', $match[1][0]]);

                continue;
            }

            $keyword = $match[2][0] ?? '';
            $name = $match[3][0] ?? '';

            if ($keyword === '#each' || $keyword === '#if') {
                $stack[] = ['kind' => ltrim($keyword, '#'), 'name' => $name, 'then' => [], 'else' => [], 'inElse' => false];
            } elseif ($keyword === 'else') {
                $top = &$stack[count($stack) - 1];
                if ($top['kind'] !== 'if') {
                    throw new InvalidArgumentException('{{else}} is only valid inside {{#if}}.');
                }
                $top['inElse'] = true;
                unset($top);
            } elseif ($keyword === '/each' || $keyword === '/if') {
                if (count($stack) < 2 || $stack[count($stack) - 1]['kind'] !== ltrim($keyword, '/')) {
                    throw new InvalidArgumentException("Unexpected {{{$keyword}}}.");
                }
                $closed = array_pop($stack);
                $append(['block', $closed['kind'], $closed['name'], $closed['then'], $closed['else']]);
            } else {
                if ($name === '') {
                    throw new InvalidArgumentException('Empty {{ }} placeholder.');
                }
                $append(['var', $name]);
            }
        }

        $append(['text', substr($template, $cursor)]);

        if (count($stack) !== 1) {
            throw new InvalidArgumentException('Unclosed {{#each}} or {{#if}} block.');
        }

        return $root['then'];
    }

    private function renderNodes(array $nodes, array $scopes): string
    {
        $out = '';

        foreach ($nodes as $node) {
            switch ($node[0]) {
                case 'text':
                    $out .= $node[1];
                    break;
                case 'var':
                    $out .= htmlspecialchars($this->stringify($this->lookup($node[1], $scopes)), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
                    break;
                case 'raw':
                    $out .= $this->stringify($this->lookup($node[1], $scopes));
                    break;
                case 'block':
                    $value = $this->lookup($node[2], $scopes);
                    if ($node[1] === 'each') {
                        foreach (is_iterable($value) ? $value : [] as $row) {
                            $out .= $this->renderNodes($node[3], array_merge($scopes, [is_array($row) ? $row : ['value' => $row]]));
                        }
                    } else {
                        $out .= $this->renderNodes($value ? $node[3] : $node[4], $scopes);
                    }
                    break;
            }
        }

        return $out;
    }

    private function lookup(string $path, array $scopes): mixed
    {
        foreach (array_reverse($scopes) as $scope) {
            $value = $scope;
            foreach (explode('.', $path) as $segment) {
                if (is_array($value) && array_key_exists($segment, $value)) {
                    $value = $value[$segment];
                } else {
                    continue 2;
                }
            }

            return $value;
        }

        return null;
    }

    private function stringify(mixed $value): string
    {
        return is_scalar($value) ? (string) $value : '';
    }
}
